import React, { useEffect } from 'react';
import axios from "axios";


function DictionarySkills() {

    useEffect(() => {
        const Skills = async () => {
            try {
                const resRoles = await axios.get('/api/Skills/')
                console.log('res=',resRoles.data)

            } catch (error) {
                console.error('Error fetching data:', error);
            }
        };

        Skills();
    }, []);
    return (
        <div className="ReportsButton">
            <div>
                <table className="skills-table">
                    <thead>
                    <tr className="skills-header">
                        <th>
                            <div><label>Добавить умение</label></div>
                            <div>
                                <input className="ModalInputUpdate" type="text" />
                            </div>
                        </th>
                        <th>
                            <div><label>Поиск</label></div>
                            <input className="ModalInputUpdate"/>
                        </th>
                    </tr>
                    </thead>
                </table>
            </div>
        </div>
    );
}

export default DictionarySkills;
